select

from t_task_info t1,t_version t2,t_product t3
where t1.is_delete = 0 and t1.version_id = t2.id and t2.product_id = t3.id

    and t3.id = #{taskInfoEntity.productId ,jdbcType=VARCHAR}



    and t1.`name` = #{taskInfoEntity.name ,jdbcType=VARCHAR}


    and t1.create_time >= #{taskInfoEntity.createTime ,jdbcType=DATETIMEOFFSET}


    and t1.end_time <= #{taskInfoEntity.endTime ,jdbcType=DATETIMEOFFSET}


    and t1.creator = #{taskInfoEntity.creator ,jdbcType=VARCHAR}


    and t1.department = #{taskInfoEntity.department ,jdbcType=VARCHAR}


    and t1.developer = #{taskInfoEntity.developer ,jdbcType=VARCHAR}


    and t1.entry_auditor = #{taskInfoEntity.entryAuditor ,jdbcType=VARCHAR}


    and t1.translator = #{taskInfoEntity.translator ,jdbcType=VARCHAR}


    and t1.translation_auditor = #{taskInfoEntity.translationAuditor ,jdbcType=VARCHAR}


    and t1.description = #{taskInfoEntity.description ,jdbcType=VARCHAR}


    and t1.state in( ${taskInfoEntity.state } )


    and t1.version_id  = #{taskInfoEntity.versionId }


    and t1.translate_type  = #{taskInfoEntity.translateType }


order by create_time desc

    LIMIT #{limit} OFFSET #{offset}

